            // GuildsStandingCommissionAtCapeOath (Mondstadt / TheLegendsWereTrue)
            ["GUILDS_STANDING_COMMISSION_AT_CAPE_OATH.title"] =
                "The Guild's Standing Commission at Cape Oath",
            ["GUILDS_STANDING_COMMISSION_AT_CAPE_OATH.pages.INITIAL.description"] =
                "The Adventurers' Guild desk has kept a commission open for years "
                + "on the old sailor's tale of treasure under Cape Oath, and every "
                + "posting-board veteran assumes it's a joke played on new recruits. "
                + "A weathered chart in the receptionist's drawer says otherwise — "
                + "the coastline in it matches nothing on the current map. She offers "
                + "you the chart itself, no questions asked, or a faster way out if "
                + "the cliffs get the better of you.",
            ["GUILDS_STANDING_COMMISSION_AT_CAPE_OATH.pages.INITIAL.options.NAB_THE_MAP.title"] =
                "Nab the Map",
