            ["HAUNTED_CAMPSITE_BELOW_DRAGONSPINE.pages.INITIAL.options.KILL.description"] =
                "Lose 8 Max HP. Obtain a random Relic.",
            ["HAUNTED_CAMPSITE_BELOW_DRAGONSPINE.pages.REST.description"] =
