            // TalesOfGuyunWereTrue (Liyue / TheLegendsWereTrue)
            ["TALES_OF_GUYUN_WERE_TRUE.title"] =
                "The Tales of Guyun Were True",
            ["TALES_OF_GUYUN_WERE_TRUE.pages.INITIAL.description"] =
                "The drowned hall under Guyun Stone Forest was supposed to be a "
                + "fisherman's tall tale, but the tide is out and the doorway is real "
                + "stone. Treasure Hoarders reached it first and left in a hurry: "
                + "overturned crates, a snuffed lantern, a lacquered chart pinned to "
                + "the wall with a knife. Your Guild commission said survey only. The "
                + "passage behind you is already taking water.",
            ["TALES_OF_GUYUN_WERE_TRUE.pages.INITIAL.options.NAB_THE_MAP.title"] =
                "Nab the Chart",
            ["TALES_OF_GUYUN_WERE_TRUE.pages.INITIAL.options.NAB_THE_MAP.description"] =
                "Receive the Hoarders' spoils chart (Spoils Map).",
            ["TALES_OF_GUYUN_WERE_TRUE.pages.INITIAL.options.SLOWLY_FIND_AN_EXIT.title"] =
                "Feel Your Way Out Slowly",
            ["TALES_OF_GUYUN_WERE_TRUE.pages.INITIAL.options.SLOWLY_FIND_AN_EXIT.description"] =
                "Lose 8 HP scraping through the flooded crawlway. Procure 1 random "
                + "Potion from a cracked Hoarder crate.",
            ["TALES_OF_GUYUN_WERE_TRUE.pages.NAB_THE_MAP.description"] =
